import { test, expect } from '@playwright/test';
import { mockApi } from './api-mock';
import fixture from './fixtures/narrative-report.json' with { type: 'json' };

// Generated by test_narrative_review.py through the worker, storage and REST.
// Synthetic document/model only; this is not measured Qwen quality evidence.
for (const viewport of [{ width: 1280, height: 800 }, { width: 1440, height: 900 }]) {
  test(`편집된 본문·문장 연결·원문 패널 ${viewport.width}`, async ({ page }, info) => {
    await page.setViewportSize(viewport);
    await mockApi(page);
    await page.route(`**/api/deep-reviews/${fixture.review.id}`, route => route.fulfill({ json: fixture.review }));
    await page.route(`**/api/deep-reviews/${fixture.review.id}/report`, route => route.fulfill({ json: fixture.report }));
    await page.route(`**/api/evidence/${fixture.evidence.evidence_id}`, route => route.fulfill({ json: fixture.evidence }));
    const errors: string[] = []; page.on('pageerror', error => errors.push(error.message));
    await page.goto(`/deep-reviews/${fixture.review.id}`);
    const reader = page.getByRole('article', { name: '심층검토 보고서 본문' });
    await expect(reader).toBeVisible();
    await expect(reader).not.toContainText('system_recommendation');
    await expect(reader.locator('.narrative-section')).toHaveCount(8);
    for (const claim of fixture.report.report.claims) {
      await expect(reader.locator(`[data-claim-id="${claim.claim_id}"] .narrative-body`)).toHaveText(claim.body);
    }
    await expect(page.locator('.narrative-records')).not.toHaveAttribute('open');
    const delivery = page.getByRole('navigation', { name: '보고서 목차' }).getByRole('link', { name: '04 수행에 영향을 주는 조건' });
    await delivery.click();
    await expect(page.locator('#narrative-delivery')).toBeFocused();
    const source = page.locator('#narrative-delivery .narrative-sources').nth(0).getByRole('button', { name: '근거 1 확인' });
    await source.click();
    const panel = page.getByRole('complementary', { name: '선택한 원문 근거' });
    await expect(panel).toBeVisible();
    await expect(panel.locator('blockquote')).toHaveText(fixture.evidence.quote);
    const box = await panel.boundingBox();
    expect(box!.x + box!.width).toBeLessThanOrEqual(viewport.width);
    await page.screenshot({ path: info.outputPath('connected-evidence.png') });
    await panel.press('Escape');
    await expect(panel).toHaveCount(0);
    await expect(source).toBeFocused();
    const link = page.locator('#narrative-delivery .narrative-connections a').nth(0);
    const target = await link.getAttribute('href'); await link.click();
    await expect(page.locator(target!)).toBeFocused();
    await reader.getByRole('button', { name: '큰 글자', exact: true }).click();
    await reader.getByRole('button', { name: '집중 읽기', exact: true }).click();
    await expect(reader).toHaveClass(/is-focused/);
    expect(await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth)).toBeLessThanOrEqual(1);
    const missingTokens = await reader.evaluate(element => {
      const tokens = ['--color-background-surface','--color-background-muted','--bo-type-body','--border-width','--radius-element','--spacing-6'];
      return tokens.filter(token => !getComputedStyle(element).getPropertyValue(token).trim());
    });
    expect(missingTokens).toEqual([]);
    await page.screenshot({ path: info.outputPath('editorial-report.png') });
    await reader.getByRole('button', { name: '집중 읽기 종료' }).click();
    expect(errors).toEqual([]);
  });
}

test('이전 보고서 읽기와 새 수정본 도착 중 편집 보존', async ({ page }) => {
  await mockApi(page);
  let report = structuredClone(fixture.report);
  let review = structuredClone(fixture.review);
  await page.route(`**/api/deep-reviews/${fixture.review.id}`, route => route.fulfill({ json: review }));
  await page.route(`**/api/deep-reviews/${fixture.review.id}/report`, route => route.fulfill({ json: report }));
  await page.route(`**/api/evidence/${fixture.evidence.evidence_id}`, route => route.fulfill({ json: fixture.evidence }));
  await page.goto(`/deep-reviews/${fixture.review.id}`);
  await page.getByRole('button', { name: '검토 의견·수정 기록' }).click();
  await page.getByLabel('수정 절 선택').selectOption('delivery');
  const blockId = fixture.report.report.sections[3].blocks[1].block_id;
  await page.getByLabel('수정 문장 선택').selectOption(blockId);
  await page.getByLabel('절 내용').fill('담당자가 편집 중인 두 번째 상세 문장');
  await page.getByLabel('담당자 이름').fill('화면 검증 담당자');
  await page.getByLabel('수정 사유').fill('초안 보존 확인');
  await expect(page.getByLabel('심층검토 의견', { exact: true })).toHaveValue('');
  report.current_revision_id = 'ffffffff-ffff-4fff-8fff-ffffffffffff';
  report.history.push({ ...report.history[0], revision_id: report.current_revision_id, sequence: 2 });
  await page.getByRole('button', { name: '최신 보고서 확인' }).click();
  await expect(page.getByText('새 보고서가 도착했습니다. 작성 중인 초안은 보존했으며 이전 보고서를 기준으로 한 저장은 차단했습니다.')).toBeVisible();
  await expect(page.getByLabel('절 내용')).toHaveValue('담당자가 편집 중인 두 번째 상세 문장');
  await expect(page.getByRole('button', { name: '새 보고서 수정본 저장' })).toBeDisabled();
  review.status = 'failed'; review.current_attempt!.status = 'failed';
  // A separate navigation verifies a cold GET can show the previous report.
  await page.goto(`/deep-reviews/${fixture.review.id}`);
  await expect(page.getByText(/이전 완성 보고서를 표시합니다/)).toBeVisible();
  await expect(page.getByRole('article', { name: '심층검토 보고서 본문' })).toBeVisible();
});

test('차단하지 않는 확인 사항을 해당 문장과 연결한다', async ({ page }) => {
  await mockApi(page);
  const report = structuredClone(fixture.report);
  const claim = report.report.claims[0];
  const message = '원문에 축약된 연도를 본문에서 풀어 썼습니다. 해당 연도는 원문과 함께 확인하십시오.';
  report.report.validation_summary.warnings += 1;
  report.validation.checks.push({ check_type: 'year_notation', status: 'warning', severity: '낮음', message, related_claim_ids: [claim.claim_id], related_evidence_ids: claim.evidence_ids });
  await page.route(`**/api/deep-reviews/${fixture.review.id}`, route => route.fulfill({ json: fixture.review }));
  await page.route(`**/api/deep-reviews/${fixture.review.id}/report`, route => route.fulfill({ json: report }));
  await page.goto(`/deep-reviews/${fixture.review.id}`);
  const reader = page.getByRole('article', { name: '심층검토 보고서 본문' });
  await expect(reader.locator(`[data-claim-id="${claim.claim_id}"]`)).toContainText(message);
  await expect(reader.locator('.narrative-note')).toContainText(`확인 필요 ${report.report.validation_summary.warnings}건`);
  await expect(reader.locator('.narrative-section')).toHaveCount(8);
});

for (const width of [1280, 1440]) {
test(`새 분석의 대조 스위치와 대조하지 않은 보고서·인용을 구분한다 ${width}`, async ({ page }, info) => {
  await page.setViewportSize({ width, height: width === 1280 ? 800 : 900 });
  await mockApi(page);
  const report = structuredClone(fixture.report);
  report.report.validation_summary.warnings += 1;
  report.validation.checks.push({ check_type: 'source_verification_skipped', status: 'warning', severity: '중대', message: '원문 인용·숫자 대조를 끈 실행입니다.', related_claim_ids: [], related_evidence_ids: [] });
  await page.route(`**/api/deep-reviews/${fixture.review.id}`, route => route.fulfill({ json: fixture.review }));
  await page.route(`**/api/deep-reviews/${fixture.review.id}/report`, route => route.fulfill({ json: report }));
  await page.route(`**/api/evidence/${fixture.evidence.evidence_id}`, route => route.fulfill({ json: { ...fixture.evidence, source_verification_enabled: false, quote: '대조하지 않은 모델의 인용 내용' } }));
  let submitted: Record<string, unknown> | undefined;
  await page.route(`**/api/deep-reviews/${fixture.review.id}/attempts`, route => {
    submitted = route.request().postDataJSON();
    return route.fulfill({ status: 202, json: { ...fixture.review.current_attempt, status: 'queued', source_verification_enabled: false } });
  });
  await page.goto(`/deep-reviews/${fixture.review.id}`);
  const reader = page.getByRole('article', { name: '심층검토 보고서 본문' });
  await expect(reader.locator('.narrative-note')).toContainText('원문 대조 미실시');
  await expect(reader.locator('.narrative-note')).not.toContainText('근거 검증 통과');
  await page.locator('#narrative-scope .narrative-sources').getByRole('button', { name: '근거 1 확인' }).click();
  const panel = page.getByRole('complementary', { name: '선택한 원문 근거' });
  await expect(panel).toContainText('모델이 인용한 내용');
  await expect(panel.locator('details')).toHaveAttribute('open');
  await page.screenshot({ path: info.outputPath('source-verification-skipped.png') });
  await panel.press('Escape');
  await reader.getByRole('button', { name: '분석 설정', exact: true }).click();
  const control = page.getByRole('checkbox', { name: '원문 인용·숫자 대조' });
  await expect(control).toBeChecked(); await control.uncheck();
  expect(await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth)).toBeLessThanOrEqual(1);
  await page.screenshot({ path: info.outputPath('verification-settings.png') });
  await page.getByLabel('담당자 이름').fill('검증 담당자');
  await page.getByRole('button', { name: '새 분석 회차로 재시도', exact: true }).click();
  await expect.poll(() => submitted?.source_verification_enabled).toBe(false);
  await expect(reader.locator('.narrative-note')).toContainText('원문 대조 미실시');
});

}
